SELECT 'ALE-THEO-002-03', d.discipline_id, (SELECT node_id FROM public.taxonomy_tree WHERE ale_id = 'ALE-THEO-002'), 3, 'Color Theory in Architecture', 'Theory of Architecture', 'concept'::public.taxonomy_node_type, 'medium'::public.exam_frequency_level, 'understand'::public.bloom_level_type, 2, ARRAY['mcq_recall'], '[{"text": "Primary colors (RYB): Red, Yellow, Blue — cannot be created by mixing other colors", "type": "fact"}, {"text": "Secondary colors: Orange (R+Y), Green (Y+B), Violet (R+B)", "type": "fact"}, {"text": "Tertiary colors: mixtures of primary and adjacent secondary (e.g., red-orange, blue-green)", "type": "fact"}, {"text": "Hue — the pure color name on the color wheel", "type": "definition"}, {"text": "Value — lightness or darkness of a color; Tint (hue + white), Shade (hue + black), Tone (hue + gray)", "type": "definition"}, {"text": "Chroma / Saturation — intensity or purity of a color; high chroma = vivid, low chroma = muted", "type": "definition"}, {"text": "Color harmonies: Complementary (opposite on wheel), Analogous (adjacent), Monochromatic (one hue, varied value), Triadic (120° apart), Split-complementary", "type": "fact"}, {"text": "Warm colors (red, orange, yellow) — advance, energize; Cool colors (blue, green, violet) — recede, calm", "type": "concept"}, {"text": "Color psychology in architecture: affects mood, perceived temperature, spatial perception (warm colors shrink space, cool colors expand)", "type": "concept"}, {"text": "Munsell Color System — hue, value, chroma notation system used in architectural specification", "type": "fact"}]'::jsonb, true, false, false, false, 'ale-theo-002-03'
FROM public.disciplines d WHERE d.acronym = 'ALE'
ON CONFLICT (ale_id) DO UPDATE SET name = EXCLUDED.name, exam_frequency = EXCLUDED.exam_frequency, bloom_level = EXCLUDED.bloom_level, difficulty = EXCLUDED.difficulty, typical_question_formats = EXCLUDED.typical_question_formats, wiki_items = EXCLUDED.wiki_items, is_computation_heavy = EXCLUDED.is_computation_heavy, three_d_lab_linked = EXCLUDED.three_d_lab_linked, updated_at = now();
