SELECT 'ALE-THEO-002-04', d.discipline_id, (SELECT node_id FROM public.taxonomy_tree WHERE ale_id = 'ALE-THEO-002'), 3, 'Organizing Principles of Design', 'Theory of Architecture', 'concept'::public.taxonomy_node_type, 'high'::public.exam_frequency_level, 'apply'::public.bloom_level_type, 2, ARRAY['mcq_recall','mcq_application'], '[{"text": "Axis — an imaginary line about which forms and spaces are arranged; most elementary organizing device", "type": "definition"}, {"text": "Symmetry — balanced arrangement about an axis; Bilateral (mirror), Radial (rotational around center), Translational (repeated along line)", "type": "definition"}, {"text": "Hierarchy — articulation of importance among forms/spaces through size, shape, placement, or treatment", "type": "definition"}, {"text": "Rhythm — regular or harmonious recurrence of elements; Regular (uniform), Flowing (continuous/organic), Progressive (gradual change)", "type": "definition"}, {"text": "Datum — a line, plane, or volume that gathers, organizes, or measures other elements by its continuity and regularity", "type": "definition"}, {"text": "Balance — visual equilibrium; Symmetrical (formal), Asymmetrical (informal/dynamic), Radial (around center point)", "type": "definition"}, {"text": "Unity & Variety — coherence and consistency (unity) balanced with visual interest and diversity (variety)", "type": "definition"}, {"text": "Emphasis / Focal Point — a dominant element that draws attention; achieved through contrast, isolation, or placement", "type": "definition"}, {"text": "Contrast — juxtaposition of opposing elements (light/dark, large/small, smooth/rough) to create visual interest", "type": "definition"}, {"text": "Harmony — agreement and pleasing arrangement of parts; achieved through repetition, continuation, or related forms", "type": "definition"}, {"text": "Proportion — the relationship of parts to one another and to the whole; mathematical or intuitive", "type": "definition"}, {"text": "Repetition — the use of the same element or form more than once to create unity and visual rhythm", "type": "concept"}]'::jsonb, true, false, false, false, 'ale-theo-002-04'
FROM public.disciplines d WHERE d.acronym = 'ALE'
ON CONFLICT (ale_id) DO UPDATE SET name = EXCLUDED.name, exam_frequency = EXCLUDED.exam_frequency, bloom_level = EXCLUDED.bloom_level, difficulty = EXCLUDED.difficulty, typical_question_formats = EXCLUDED.typical_question_formats, wiki_items = EXCLUDED.wiki_items, is_computation_heavy = EXCLUDED.is_computation_heavy, three_d_lab_linked = EXCLUDED.three_d_lab_linked, updated_at = now();
