SELECT 'ALE-THEO-002-05', d.discipline_id, (SELECT node_id FROM public.taxonomy_tree WHERE ale_id = 'ALE-THEO-002'), 3, 'Form Transformations', 'Theory of Architecture', 'concept'::public.taxonomy_node_type, 'medium'::public.exam_frequency_level, 'apply'::public.bloom_level_type, 2, ARRAY['mcq_application'], '[{"text": "Additive Transformation — adding elements/volumes to a base form to create complexity", "type": "definition"}, {"text": "Subtractive Transformation — removing portions of a form to create voids, recesses, or spatial interest", "type": "definition"}, {"text": "Dimensional Transformation — altering one or more dimensions while maintaining identity (stretch, compress)", "type": "definition"}, {"text": "Additive forms: centralized (around center), linear (along axis), radial (from center outward), clustered (grouped), grid (regular matrix)", "type": "fact"}, {"text": "Subtractive forms: voids, openings, courtyards — carved from a solid mass", "type": "fact"}, {"text": "Articulation — the manner in which surfaces of a form come together; reveals structure, joints, transitions", "type": "definition"}]'::jsonb, true, false, false, false, 'ale-theo-002-05'
FROM public.disciplines d WHERE d.acronym = 'ALE'
