SELECT 'ALE-THEO-002-06', d.discipline_id, (SELECT node_id FROM public.taxonomy_tree WHERE ale_id = 'ALE-THEO-002'), 3, 'Spatial Organizations', 'Theory of Architecture', 'concept'::public.taxonomy_node_type, 'high'::public.exam_frequency_level, 'apply'::public.bloom_level_type, 2, ARRAY['mcq_application','design_application'], '[{"text": "Linear Organization — spaces arranged in a sequence along a line or path; has direction and movement", "type": "definition"}, {"text": "Centralized Organization — spaces grouped around a dominant central space; stable, concentrated", "type": "definition"}, {"text": "Radial Organization — linear arms extending from a central core; combines centralized and linear", "type": "definition"}, {"text": "Clustered Organization — spaces grouped by proximity or shared visual trait; flexible, can be asymmetrical", "type": "definition"}, {"text": "Grid Organization — spaces organized by a regular three-dimensional modular grid; systematic, expandable", "type": "definition"}, {"text": "Spatial relationships: space within a space, interlocking spaces, adjacent spaces, spaces linked by a common space", "type": "concept"}, {"text": "Circulation patterns: linear, radial, spiral, grid, composite — define how users move through space", "type": "concept"}, {"text": "Approach and entry: frontal, oblique, spiral — how one arrives at and enters a building", "type": "concept"}]'::jsonb, true, false, false, false, 'ale-theo-002-06'
