SELECT 'ALE-THEO-002-07', d.discipline_id, (SELECT node_id FROM public.taxonomy_tree WHERE ale_id = 'ALE-THEO-002'), 3, 'Architectural Elements by Function', 'Theory of Architecture', 'concept'::public.taxonomy_node_type, 'medium'::public.exam_frequency_level, 'remember'::public.bloom_level_type, 2, ARRAY['mcq_recall'], '[{"text": "Structural elements — columns, beams, walls, slabs, arches, vaults, domes, trusses; carry loads", "type": "fact"}, {"text": "Circulatory elements — corridors, hallways, stairs, ramps, elevators, escalators; enable movement", "type": "fact"}, {"text": "Protective elements — roofs, walls, foundations, insulation, waterproofing; shelter from weather", "type": "fact"}, {"text": "Decorative elements — moldings, cornices, columns (non-structural), reliefs, carvings; aesthetic enhancement", "type": "fact"}, {"text": "Need-specific elements — elements determined by building type (e.g., altar in church, stage in theater, kitchen in house)", "type": "fact"}, {"text": "Fenestration — the arrangement, proportioning, and design of windows and openings in a building", "type": "definition"}, {"text": "Vestibule — transitional entry space between exterior and interior", "type": "definition"}, {"text": "Cortile — Italian term for an internal courtyard surrounded by an arcade", "type": "definition"}, {"text": "Niche — a recess in a wall, often for display of sculpture or ornament", "type": "definition"}]'::jsonb, true, false, false, false, 'ale-theo-002-07'
