SELECT 'ALE-THEO-004-04', d.discipline_id, (SELECT node_id FROM public.taxonomy_tree WHERE ale_id = 'ALE-THEO-004'), 3, 'Gestalt Principles of Visual Perception', 'Theory of Architecture', 'concept'::public.taxonomy_node_type, 'high'::public.exam_frequency_level, 'understand'::public.bloom_level_type, 2, ARRAY['mcq_recall','mcq_application'], '[{"text": "Gestalt Psychology — ''the whole is greater than the sum of its parts''; how the brain organizes visual information", "type": "definition"}, {"text": "Figure-Ground — perception of objects (figure) against background (ground); fundamental spatial reading", "type": "definition"}, {"text": "Proximity — elements close together are perceived as a group", "type": "definition"}, {"text": "Similarity — elements sharing visual characteristics (shape, color, size) are perceived as related", "type": "definition"}, {"text": "Continuity — the eye follows smooth, continuous lines and curves rather than abrupt changes in direction", "type": "definition"}, {"text": "Closure — the mind completes incomplete shapes; we perceive whole forms even when parts are missing", "type": "definition"}, {"text": "Common Fate — elements moving in the same direction are perceived as grouped", "type": "definition"}, {"text": "Prägnanz (Good Form/Simplicity) — tendency to perceive the simplest, most regular interpretation of ambiguous stimuli", "type": "definition"}, {"text": "Application in architecture: façade composition, spatial hierarchy, visual grouping of buildings, urban design", "type": "concept"}]'::jsonb, true, false, false, false, 'ale-theo-004-04'
