SELECT 'ALE-THEO-004-05', d.discipline_id, (SELECT node_id FROM public.taxonomy_tree WHERE ale_id = 'ALE-THEO-004'), 3, 'Wayfinding & Spatial Legibility', 'Theory of Architecture', 'concept'::public.taxonomy_node_type, 'high'::public.exam_frequency_level, 'understand'::public.bloom_level_type, 2, ARRAY['mcq_recall','mcq_application'], '[{"text": "Kevin Lynch — ''The Image of the City'' (1960); how people perceive and navigate urban environments", "type": "fact"}, {"text": "Paths — channels along which people move; streets, walkways, corridors; the dominant element", "type": "definition"}, {"text": "Edges — linear boundaries between areas; walls, shorelines, railroad tracks; perceived as barriers or seams", "type": "definition"}, {"text": "Districts — medium-to-large areas with common, recognizable character; e.g., Chinatown, financial district", "type": "definition"}, {"text": "Nodes — strategic focal points; junctions, intersections, plazas; places of convergence and decision", "type": "definition"}, {"text": "Landmarks — external point references used for orientation; distinctive, visible, memorable objects or buildings", "type": "definition"}, {"text": "Cognitive Mapping — mental images/maps people form of their environment; basis for navigation and spatial understanding", "type": "definition"}, {"text": "Imageability (Legibility) — quality of a place that makes it easy to form a clear mental image; ''a good city is one that can be read''", "type": "definition"}, {"text": "Wayfinding design: signage, spatial hierarchy, sightlines, differentiation of spaces, landmarks as anchors", "type": "concept"}]'::jsonb, true, false, false, false, 'ale-theo-004-05'
