SELECT 'ALE-THEO-004-06', d.discipline_id, (SELECT node_id FROM public.taxonomy_tree WHERE ale_id = 'ALE-THEO-004'), 3, 'Psychology of Space & Behavior', 'Theory of Architecture', 'concept'::public.taxonomy_node_type, 'medium'::public.exam_frequency_level, 'understand'::public.bloom_level_type, 2, ARRAY['mcq_recall'], '[{"text": "Biophilia Hypothesis — E.O. Wilson (1984); innate human affinity for nature; drives biophilic design", "type": "definition"}, {"text": "Prospect-Refuge Theory — Jay Appleton (''The Experience of Landscape,'' 1975); preference for views (prospect) with sense of safety (refuge)", "type": "definition"}, {"text": "Place Attachment — emotional bond between people and their physical environment; sense of belonging", "type": "definition"}, {"text": "Sense of Place (Genius Loci) — Christian Norberg-Schulz; the unique character and atmosphere of a specific location", "type": "definition"}, {"text": "Phenomenology of Architecture — Juhani Pallasmaa (''The Eyes of the Skin,'' 2005); multi-sensory experience of space beyond the visual", "type": "fact"}, {"text": "Affordance — James J. Gibson; perceived potential for action in the environment; a door handle ''affords'' pulling", "type": "definition"}, {"text": "Environmental determinism vs. possibilism — do spaces determine behavior or merely enable/constrain it?", "type": "concept"}, {"text": "Emotional response to spatial qualities: compression/release, light/shadow, enclosure/openness, warmth/coolness", "type": "concept"}]'::jsonb, true, false, false, false, 'ale-theo-004-06'
FROM public.disciplines d WHERE d.acronym = 'ALE'
