-- ALE-THEO-005
INSERT INTO public.taxonomy_tree (ale_id, discipline_id, parent_id, level, name, subject_area, node_type, exam_frequency, bloom_level, difficulty, typical_question_formats, wiki_items, is_leaf, is_cross_ref_only, is_computation_heavy, three_d_lab_linked, slug)
SELECT 'ALE-THEO-005-03', d.discipline_id, (SELECT node_id FROM public.taxonomy_tree WHERE ale_id = 'ALE-THEO-005'), 3, 'Passive Design Strategies', 'Theory of Architecture', 'concept'::public.taxonomy_node_type, 'high'::public.exam_frequency_level, 'apply'::public.bloom_level_type, 2, ARRAY['mcq_application','design_application'], '[{"text": "Cross-ventilation — openings on opposite walls allowing wind to flow through; most effective passive cooling", "type": "definition"}, {"text": "Stack ventilation (chimney effect) — warm air rises and exits through high openings, drawing cool air in below", "type": "definition"}, {"text": "Shading devices: horizontal overhang (north/south), vertical fins (east/west), egg-crate (combination), brise-soleil (sun breaker)", "type": "fact"}, {"text": "Elevated floors — raise living area above ground for ventilation, flood protection, pest avoidance (bahay kubo principle)", "type": "fact"}, {"text": "Thermal mass — materials that absorb heat during day and release at night (concrete, stone, brick); effective in dry climates", "type": "definition"}, {"text": "Insulation — reducing heat transfer through roof and walls; critical for roof in tropics (greatest heat gain)", "type": "fact"}, {"text": "Roof design: steep pitch for rain runoff, ventilated attic space, light-colored roofing to reflect solar radiation", "type": "concept"}, {"text": "Daylighting strategies: clerestory windows, light shelves, skylights, light courts; reduce artificial lighting", "type": "fact"}, {"text": "Landscape as climate modifier: shade trees (windward side), ground cover to reduce heat reflection, water features for evaporative cooling", "type": "concept"}, {"text": "Breezeway — covered outdoor passage designed to channel and accelerate natural airflow", "type": "definition"}]'::jsonb, true, false, false, false, 'ale-theo-005-03'
FROM public.disciplines d WHERE d.acronym = 'ALE'
ON CONFLICT (ale_id) DO UPDATE SET name = EXCLUDED.name, exam_frequency = EXCLUDED.exam_frequency, bloom_level = EXCLUDED.bloom_level, difficulty = EXCLUDED.difficulty, typical_question_formats = EXCLUDED.typical_question_formats, wiki_items = EXCLUDED.wiki_items, is_computation_heavy = EXCLUDED.is_computation_heavy, three_d_lab_linked = EXCLUDED.three_d_lab_linked, updated_at = now();
INSERT INTO public.taxonomy_tree (ale_id, discipline_id, parent_id, level, name, subject_area, node_type, exam_frequency, bloom_level, difficulty, typical_question_formats, wiki_items, is_leaf, is_cross_ref_only, is_computation_heavy, three_d_lab_linked, slug)
SELECT 'ALE-THEO-005-04', d.discipline_id, (SELECT node_id FROM public.taxonomy_tree WHERE ale_id = 'ALE-THEO-005'), 3, 'Sun Shading Devices & Techniques', 'Theory of Architecture', 'concept'::public.taxonomy_node_type, 'medium'::public.exam_frequency_level, 'apply'::public.bloom_level_type, 3, ARRAY['mcq_application','design_application'], '[{"text": "Horizontal overhang — effective for south-facing walls (high sun angle); depth calculated from latitude and desired cut-off angle", "type": "fact"}, {"text": "Vertical fins — effective for east/west-facing walls (low sun angle); block morning/afternoon sun", "type": "fact"}, {"text": "Egg-crate / combined device — horizontal + vertical elements; effective for walls facing between cardinal directions", "type": "fact"}, {"text": "Brise-soleil — ''sun breaker''; fixed or adjustable louvers on building exterior (Le Corbusier popularized)", "type": "definition"}, {"text": "Mashrabiya / lattice screen — perforated screen filtering light while maintaining privacy and airflow (Islamic/tropical precedent)", "type": "fact"}, {"text": "Louvers — adjustable slats for controlling light and ventilation; horizontal, vertical, or angled", "type": "definition"}, {"text": "Solar shading coefficient (SC) and Solar Heat Gain Coefficient (SHGC) — metrics for glazing performance", "type": "definition"}, {"text": "Double skin façade — outer layer + cavity + inner layer; reduces solar heat gain while maintaining transparency", "type": "fact"}]'::jsonb, true, false, false, false, 'ale-theo-005-04'
FROM public.disciplines d WHERE d.acronym = 'ALE'
