SELECT 'ALE-THEO-005-05', d.discipline_id, (SELECT node_id FROM public.taxonomy_tree WHERE ale_id = 'ALE-THEO-005'), 3, 'Biophilic & Sustainable Design Theory', 'Theory of Architecture', 'concept'::public.taxonomy_node_type, 'medium'::public.exam_frequency_level, 'understand'::public.bloom_level_type, 2, ARRAY['mcq_recall'], '[{"text": "Biophilic Design — integrating nature and natural systems into the built environment; based on E.O. Wilson''s Biophilia Hypothesis", "type": "definition"}, {"text": "14 Patterns of Biophilic Design (Terrapin Bright Green, 2014): visual connection to nature, non-visual, thermal airflow variability, presence of water, dynamic/diffuse light, complexity/order, prospect, refuge, mystery, risk/peril", "type": "fact"}, {"text": "Sustainable design principles: reduce energy, conserve water, minimize waste, use renewable materials, enhance indoor environment", "type": "concept"}, {"text": "LEED (Leadership in Energy and Environmental Design) — US green building rating system", "type": "fact"}, {"text": "BERDE (Building for Ecologically Responsive Design Excellence) — Philippine green building rating system", "type": "fact"}, {"text": "Ken Yeang (Malaysia) — bioclimatic skyscrapers; vertical landscaping, sky courts; Menara Mesiniaga", "type": "fact"}, {"text": "Net-zero energy buildings — produce as much energy as they consume annually through renewable sources", "type": "definition"}, {"text": "Adaptive reuse — repurposing existing buildings for new functions; reducing demolition waste and embodied energy", "type": "definition"}]'::jsonb, true, false, false, false, 'ale-theo-005-05'
FROM public.disciplines d WHERE d.acronym = 'ALE'
