-- ALE-THEO-006
INSERT INTO public.taxonomy_tree (ale_id, discipline_id, parent_id, level, name, subject_area, node_type, exam_frequency, bloom_level, difficulty, typical_question_formats, wiki_items, is_leaf, is_cross_ref_only, is_computation_heavy, three_d_lab_linked, slug)
SELECT 'ALE-THEO-006-03', d.discipline_id, (SELECT node_id FROM public.taxonomy_tree WHERE ale_id = 'ALE-THEO-006'), 3, 'Mid-Century & Late Modern Masters', 'Theory of Architecture', 'concept'::public.taxonomy_node_type, 'high'::public.exam_frequency_level, 'analyze'::public.bloom_level_type, 3, ARRAY['mcq_recall','mcq_application'], '[{"text": "Louis Kahn (1901-1974) — ''served and servant spaces''; monumentality through geometric purity; ''What does the building want to be?''", "type": "fact"}, {"text": "Kahn — Salk Institute (1965), Kimbell Art Museum (1972), National Assembly of Bangladesh (1982)", "type": "fact"}, {"text": "Alvar Aalto (1898-1976) — Finnish humanistic modernism; organic forms, natural materials, user-centered; Paimio Sanatorium, Villa Mairea", "type": "fact"}, {"text": "Oscar Niemeyer (1907-2012) — Brazilian free-form modernism; ''Each one sees what he wishes''; Cathedral of Brasília, Brasília plan (with Costa)", "type": "fact"}, {"text": "Eero Saarinen (1910-1961) — sculptural modernism; TWA Terminal (1962), Gateway Arch (1965), Dulles Airport", "type": "fact"}, {"text": "Pier Luigi Nervi (1891-1979) — ''Shell builder''; reinforced concrete structures; Pirelli Tower (Milan), Palazzetto dello Sport (Rome)", "type": "fact"}, {"text": "Felix Candela (1910-1997) — thin-shell concrete hyperbolic paraboloids; Los Manantiales Restaurant (Mexico City)", "type": "fact"}, {"text": "Buckminster Fuller (1895-1983) — ''Design Science''; geodesic dome; ''doing more with less''; Dymaxion House", "type": "fact"}, {"text": "Frei Otto (1925-2015) — lightweight tensile structures; Munich Olympic Stadium (1972); nature-inspired minimal surfaces", "type": "fact"}, {"text": "Kenzo Tange (1913-2005) — Japanese Metabolism; Hiroshima Peace Memorial, Tokyo City Hall; bridging tradition and modernism", "type": "fact"}]'::jsonb, true, false, false, false, 'ale-theo-006-03'
FROM public.disciplines d WHERE d.acronym = 'ALE'
ON CONFLICT (ale_id) DO UPDATE SET name = EXCLUDED.name, exam_frequency = EXCLUDED.exam_frequency, bloom_level = EXCLUDED.bloom_level, difficulty = EXCLUDED.difficulty, typical_question_formats = EXCLUDED.typical_question_formats, wiki_items = EXCLUDED.wiki_items, is_computation_heavy = EXCLUDED.is_computation_heavy, three_d_lab_linked = EXCLUDED.three_d_lab_linked, updated_at = now();
