SELECT 'ALE-THEO-006-04', d.discipline_id, (SELECT node_id FROM public.taxonomy_tree WHERE ale_id = 'ALE-THEO-006'), 3, 'Pritzker Prize Laureates & Contemporary Architects', 'Theory of Architecture', 'concept'::public.taxonomy_node_type, 'high'::public.exam_frequency_level, 'remember'::public.bloom_level_type, 2, ARRAY['mcq_recall'], '[{"text": "Pritzker Architecture Prize — established 1979 by Hyatt Foundation; ''Nobel Prize of Architecture''; annual award to living architect(s)", "type": "definition"}, {"text": "Tadao Ando (Pritzker 1995) — self-taught; concrete and light as primary materials; Church of the Light, Water Temple", "type": "fact"}, {"text": "Renzo Piano (Pritzker 1998) — Centre Pompidou (with Rogers, 1977), The Shard (London), Kansai Airport; technology + craft", "type": "fact"}, {"text": "Norman Foster (Pritzker 1999) — High-Tech: 30 St Mary Axe (Gherkin), Reichstag dome, HSBC HQ Hong Kong", "type": "fact"}, {"text": "Rem Koolhaas (Pritzker 2000) — OMA; ''Delirious New York''; CCTV HQ Beijing; provocative theory + practice", "type": "fact"}, {"text": "Zaha Hadid (Pritzker 2004) — first woman laureate; parametric flowing forms; Heydar Aliyev Center, MAXXI Rome", "type": "fact"}, {"text": "I.M. Pei (Pritzker 1983) — geometric modernism; Louvre Pyramid (1989), National Gallery East Wing, EDSA Shangri-La (Manila)", "type": "fact"}, {"text": "Frank Gehry (Pritzker 1989) — Deconstructivism; Guggenheim Bilbao (1997), Walt Disney Concert Hall; ''Bilbao Effect''", "type": "fact"}, {"text": "Richard Meier (Pritzker 1984) — white modernism; Getty Center, Jubilee Church (Rome), Barcelona MACBA", "type": "fact"}, {"text": "Robert Venturi (Pritzker 1991) — ''Less is a bore''; ''Complexity and Contradiction'' (1966); ''Learning from Las Vegas'' (1972)", "type": "fact"}, {"text": "Peter Zumthor (Pritzker 2009) — phenomenological architecture; Therme Vals (1996), Kolumba Museum; atmosphere and materiality", "type": "fact"}, {"text": "Shigeru Ban (Pritzker 2014) — humanitarian architecture; paper tube structures; disaster relief shelters", "type": "fact"}, {"text": "Alejandro Aravena (Pritzker 2016) — social housing innovation; ''half-a-good-house'' (ELEMENTAL); participatory design", "type": "fact"}, {"text": "Diébédo Francis Kéré (Pritzker 2022) — community-built architecture; local materials; ventilation innovation; Gando School", "type": "fact"}, {"text": "Santiago Calatrava — engineer-architect; Turning Torso (Malmö), Milwaukee Art Museum, City of Arts and Sciences (Valencia)", "type": "fact"}, {"text": "Jørn Utzon (Pritzker 2003) — Sydney Opera House (1973); sculptural expressionism; additive architecture", "type": "fact"}, {"text": "Michael Graves (Pritzker not awarded but ALE-relevant) — Postmodern; Portland Building, Disney Swan & Dolphin; color and historical reference", "type": "fact"}, {"text": "Liu Jiakun (Pritzker 2025) — Chinese; post-earthquake reconstruction; material honesty; Ji Art Museum", "type": "fact"}, {"text": "Smiljan Radić Clarke (Pritzker 2026) — Chilean; raw materials, sculptural intervention; Serpentine Pavilion (2014)", "type": "fact"}]'::jsonb, true, false, false, false, 'ale-theo-006-04'
FROM public.disciplines d WHERE d.acronym = 'ALE'
ON CONFLICT (ale_id) DO UPDATE SET name = EXCLUDED.name, exam_frequency = EXCLUDED.exam_frequency, bloom_level = EXCLUDED.bloom_level, difficulty = EXCLUDED.difficulty, typical_question_formats = EXCLUDED.typical_question_formats, wiki_items = EXCLUDED.wiki_items, is_computation_heavy = EXCLUDED.is_computation_heavy, three_d_lab_linked = EXCLUDED.three_d_lab_linked, updated_at = now();
