SELECT 'ALE-THEO-006-05', d.discipline_id, (SELECT node_id FROM public.taxonomy_tree WHERE ale_id = 'ALE-THEO-006'), 3, 'Filipino Architects & Design Philosophies', 'Theory of Architecture', 'concept'::public.taxonomy_node_type, 'high'::public.exam_frequency_level, 'remember'::public.bloom_level_type, 2, ARRAY['mcq_recall'], '[{"text": "Juan Nakpil (1899-1986) — National Artist 1973; ''Dean of Filipino Architects''; advocated indigenous materials (bamboo, thatch); Quezon Memorial Circle", "type": "fact"}, {"text": "Pablo Antonio (1901-1975) — National Artist 1976; fused Gothic/Baroque with modern design; Ideal Theater, FEU buildings, Far Eastern University campus", "type": "fact"}, {"text": "Leandro Locsin (1928-1994) — National Artist 1990; ''Poet of Space''; concept of Bipolarity; floating volumes in concrete; CCP, PICC, Istana Nurul Iman", "type": "fact"}, {"text": "Locsin''s Theory of Bipolarity — dynamic formation of architectural forms and spaces through opposing forces and geometric clarity", "type": "definition"}, {"text": "Ildefonso Santos Jr. (1929-2014) — National Artist 2006 (Landscape Architecture); ''Father of Philippine Landscape Architecture''; Serial Vision theory", "type": "fact"}, {"text": "Santos'' Serial Vision — landscapes unfold in experiential sequences, not static views; pioneered use of indigenous plants", "type": "definition"}, {"text": "Francisco ''Bobby'' Mañosa (1931-2020) — National Artist 2018; neo-vernacular; Coconut Palace (1981), EDSA Shrine; bahay kubo as design DNA", "type": "fact"}, {"text": "Mañosa''s Philosophy — modernize the native, not nativize the modern; Filipino identity expressed in contemporary forms", "type": "definition"}, {"text": "Juan Arellano (1888-1960) — Art Deco master; Metropolitan Theater (1931), Manila Central Post Office, Jones Bridge; first Filipino architect of national prominence", "type": "fact"}, {"text": "Tomas Mapua (1888-1965) — founder of Mapua Institute of Technology (1925); first licensed Filipino architect; De La Salle University building", "type": "fact"}, {"text": "Felino Palafox Jr. — contemporary urban planner; Clark Green City masterplan; ''Green Urbanism''; Rockwell Center, BGC planning", "type": "fact"}, {"text": "William Coscolluela — PHIVOLCS building; contemporary Filipino modernist", "type": "fact"}, {"text": "Froilan Hong — promoted modern Filipino design; institutional buildings", "type": "fact"}, {"text": "Carlos Arguelles (1918-1996) — Manila Hilton, Philbanking Building; modern commercial architecture", "type": "fact"}, {"text": "Vernacularization — design strategy expressing distinct national character by localizing architecture through indigenous social, cultural, political, and historical contexts", "type": "definition"}]'::jsonb, true, false, false, false, 'ale-theo-006-05'
FROM public.disciplines d WHERE d.acronym = 'ALE'
ON CONFLICT (ale_id) DO UPDATE SET name = EXCLUDED.name, exam_frequency = EXCLUDED.exam_frequency, bloom_level = EXCLUDED.bloom_level, difficulty = EXCLUDED.difficulty, typical_question_formats = EXCLUDED.typical_question_formats, wiki_items = EXCLUDED.wiki_items, is_computation_heavy = EXCLUDED.is_computation_heavy, three_d_lab_linked = EXCLUDED.three_d_lab_linked, updated_at = now();

-- ALE-THEO-007
INSERT INTO public.taxonomy_tree (ale_id, discipline_id, parent_id, level, name, subject_area, node_type, exam_frequency, bloom_level, difficulty, typical_question_formats, wiki_items, is_leaf, is_cross_ref_only, is_computation_heavy, three_d_lab_linked, slug)
SELECT 'ALE-THEO-007-01', d.discipline_id, (SELECT node_id FROM public.taxonomy_tree WHERE ale_id = 'ALE-THEO-007'), 3, 'Pre-Modern & Early Modern Movements', 'Theory of Architecture', 'concept'::public.taxonomy_node_type, 'medium'::public.exam_frequency_level, 'understand'::public.bloom_level_type, 2, ARRAY['mcq_recall'], '[{"text": "Arts and Crafts Movement (1860s-1910s) — William Morris; handcraft over machine production; truth to materials; medieval guild ideals", "type": "fact"}, {"text": "Art Nouveau (1890-1910) — organic, curvilinear forms; Gaudí, Horta, Guimard; whiplash line; total design (architecture + furnishings)", "type": "fact"}, {"text": "Beaux-Arts (19th-early 20th c.) — École des Beaux-Arts, Paris; monumental classicism, axial symmetry, rich decoration", "type": "fact"}, {"text": "Art Deco (1920s-1940s) — geometric ornament, luxurious materials, machine-age imagery; Chrysler Building, Empire State Building", "type": "fact"}, {"text": "Futurism (1909+) — Antonio Sant''Elia; speed, technology, dynamic forms; ''Città Nuova'' (1914, unbuilt)", "type": "fact"}, {"text": "Expressionism (1910s-1920s) — Erich Mendelsohn (Einstein Tower); emotional, sculptural, non-rational forms; Hans Scharoun", "type": "fact"}]'::jsonb, true, false, false, false, 'ale-theo-007-01'
FROM public.disciplines d WHERE d.acronym = 'ALE'
ON CONFLICT (ale_id) DO UPDATE SET name = EXCLUDED.name, exam_frequency = EXCLUDED.exam_frequency, bloom_level = EXCLUDED.bloom_level, difficulty = EXCLUDED.difficulty, typical_question_formats = EXCLUDED.typical_question_formats, wiki_items = EXCLUDED.wiki_items, is_computation_heavy = EXCLUDED.is_computation_heavy, three_d_lab_linked = EXCLUDED.three_d_lab_linked, updated_at = now();
INSERT INTO public.taxonomy_tree (ale_id, discipline_id, parent_id, level, name, subject_area, node_type, exam_frequency, bloom_level, difficulty, typical_question_formats, wiki_items, is_leaf, is_cross_ref_only, is_computation_heavy, three_d_lab_linked, slug)
SELECT 'ALE-THEO-007-02', d.discipline_id, (SELECT node_id FROM public.taxonomy_tree WHERE ale_id = 'ALE-THEO-007'), 3, 'Modern Movements', 'Theory of Architecture', 'concept'::public.taxonomy_node_type, 'high'::public.exam_frequency_level, 'understand'::public.bloom_level_type, 2, ARRAY['mcq_recall','mcq_application'], '[{"text": "Bauhaus (1919-1933) — founded by Gropius; unity of art, craft, and technology; Weimar → Dessau → Berlin", "type": "fact"}, {"text": "International Style (1920s-1960s) — term coined by Hitchcock & Johnson (MoMA 1932); glass curtain wall, flat roofs, volume over mass, no ornament", "type": "fact"}, {"text": "De Stijl (1917-1931) — Mondrian, Rietveld; primary colors, orthogonal geometry; Rietveld Schröder House (1924)", "type": "fact"}, {"text": "Constructivism (1920s) — Russian; architecture as social instrument; structural expression; Tatlin''s Tower (unbuilt)", "type": "fact"}, {"text": "Brutalism (1950s-1970s) — béton brut (raw concrete); honest materials; social housing; Smithsons, Le Corbusier''s Unité", "type": "fact"}, {"text": "Metabolism (Japan, 1960s) — Tange, Kurokawa, Kikutake; megastructures, biological growth metaphor; Nakagin Capsule Tower", "type": "fact"}, {"text": "High-Tech (1970s+) — Piano, Rogers, Foster; exposed structure and services; Centre Pompidou, Lloyd''s Building, Gherkin", "type": "fact"}, {"text": "Minimalism — reduction to essential elements; Tadao Ando, SANAA, John Pawson; silence and light", "type": "fact"}]'::jsonb, true, false, false, false, 'ale-theo-007-02'
FROM public.disciplines d WHERE d.acronym = 'ALE'
ON CONFLICT (ale_id) DO UPDATE SET name = EXCLUDED.name, exam_frequency = EXCLUDED.exam_frequency, bloom_level = EXCLUDED.bloom_level, difficulty = EXCLUDED.difficulty, typical_question_formats = EXCLUDED.typical_question_formats, wiki_items = EXCLUDED.wiki_items, is_computation_heavy = EXCLUDED.is_computation_heavy, three_d_lab_linked = EXCLUDED.three_d_lab_linked, updated_at = now();
INSERT INTO public.taxonomy_tree (ale_id, discipline_id, parent_id, level, name, subject_area, node_type, exam_frequency, bloom_level, difficulty, typical_question_formats, wiki_items, is_leaf, is_cross_ref_only, is_computation_heavy, three_d_lab_linked, slug)
SELECT 'ALE-THEO-007-03', d.discipline_id, (SELECT node_id FROM public.taxonomy_tree WHERE ale_id = 'ALE-THEO-007'), 3, 'Postmodern & Contemporary Theories', 'Theory of Architecture', 'concept'::public.taxonomy_node_type, 'medium'::public.exam_frequency_level, 'understand'::public.bloom_level_type, 3, ARRAY['mcq_recall'], '[{"text": "Postmodernism (1960s-1990s) — reaction against modernist austerity; irony, historical reference, ornament; Venturi, Graves, Moore", "type": "fact"}, {"text": "Deconstructivism (1980s+) — fragmentation, distortion, unpredictability; Gehry, Hadid, Libeskind, Eisenman, Koolhaas", "type": "fact"}, {"text": "Critical Regionalism — Kenneth Frampton (1983); modern techniques + local culture, climate, materials; resists universal modernism", "type": "fact"}, {"text": "Parametricism — Patrik Schumacher (2008); algorithmic/computational design; complex curvilinear geometries; Zaha Hadid Architects", "type": "fact"}, {"text": "Sustainable/Green Architecture — ecological responsibility; LEED, Passive House, biomimicry, cradle-to-cradle; net-zero goals", "type": "fact"}, {"text": "Phenomenology — architecture as multi-sensory experience; Zumthor (''Atmospheres''), Pallasmaa (''The Eyes of the Skin''), Holl", "type": "fact"}, {"text": "New Urbanism (1980s+) — Andrés Duany, Elizabeth Plater-Zyberk; walkable neighborhoods, mixed-use, traditional urban form", "type": "fact"}, {"text": "Organic Architecture (modern interpretation) — biomimicry, computational optimization, nature-derived forms; beyond Wright''s original", "type": "concept"}]'::jsonb, true, false, false, false, 'ale-theo-007-03'
FROM public.disciplines d WHERE d.acronym = 'ALE'
ON CONFLICT (ale_id) DO UPDATE SET name = EXCLUDED.name, exam_frequency = EXCLUDED.exam_frequency, bloom_level = EXCLUDED.bloom_level, difficulty = EXCLUDED.difficulty, typical_question_formats = EXCLUDED.typical_question_formats, wiki_items = EXCLUDED.wiki_items, is_computation_heavy = EXCLUDED.is_computation_heavy, three_d_lab_linked = EXCLUDED.three_d_lab_linked, updated_at = now();
INSERT INTO public.taxonomy_tree (ale_id, discipline_id, parent_id, level, name, subject_area, node_type, exam_frequency, bloom_level, difficulty, typical_question_formats, wiki_items, is_leaf, is_cross_ref_only, is_computation_heavy, three_d_lab_linked, slug)
SELECT 'ALE-THEO-007-04', d.discipline_id, (SELECT node_id FROM public.taxonomy_tree WHERE ale_id = 'ALE-THEO-007'), 3, 'Seminal Architectural Texts & Treatises', 'Theory of Architecture', 'concept'::public.taxonomy_node_type, 'medium'::public.exam_frequency_level, 'remember'::public.bloom_level_type, 2, ARRAY['mcq_recall'], '[{"text": "Vitruvius — ''De Architectura'' (c. 25 BCE): ten books; Firmitas, Utilitas, Venustas; first systematic architectural treatise", "type": "fact"}, {"text": "Alberti — ''De Re Aedificatoria'' (1452): Renaissance treatise; concinnitas; architecture as intellectual art", "type": "fact"}, {"text": "Palladio — ''I Quattro Libri dell''Architettura'' (1570): proportional systems, villa types, classical orders", "type": "fact"}, {"text": "Le Corbusier — ''Vers une Architecture'' / ''Towards a New Architecture'' (1923): ''eyes that do not see''; machine aesthetic", "type": "fact"}, {"text": "Le Corbusier — ''The Modulor'' (1948): human-scale proportional system based on golden ratio and Fibonacci", "type": "fact"}, {"text": "Robert Venturi — ''Complexity and Contradiction in Architecture'' (1966): challenged modernist simplicity; ''less is a bore''", "type": "fact"}, {"text": "Venturi, Scott Brown & Izenour — ''Learning from Las Vegas'' (1972): ''decorated shed'' vs. ''duck''; populist architecture", "type": "fact"}, {"text": "Francis D.K. Ching — ''Architecture: Form, Space, and Order'' (1979): visual vocabulary of architecture; primary reference for TOA courses", "type": "fact"}, {"text": "Kevin Lynch — ''The Image of the City'' (1960): paths, edges, districts, nodes, landmarks; urban legibility", "type": "fact"}, {"text": "Christopher Alexander — ''A Pattern Language'' (1977): 253 patterns for designing livable environments; community-up approach", "type": "fact"}, {"text": "George Salvan — ''Architectural Theories of Design'' (1999): Filipino TOA reference; behavioral, ecological, and design approaches", "type": "fact"}, {"text": "Ernst Neufert — ''Architects'' Data / Bauentwurfslehre'' (1936): standard reference for human dimensions, space requirements, building types", "type": "fact"}, {"text": "Rem Koolhaas — ''Delirious New York'' (1978) and ''S,M,L,XL'' (1995): urban theory, bigness, congestion culture", "type": "fact"}, {"text": "Juhani Pallasmaa — ''The Eyes of the Skin'' (2005): critique of ocularcentrism; multi-sensory architecture", "type": "fact"}]'::jsonb, true, false, false, false, 'ale-theo-007-04'
FROM public.disciplines d WHERE d.acronym = 'ALE'
ON CONFLICT (ale_id) DO UPDATE SET name = EXCLUDED.name, exam_frequency = EXCLUDED.exam_frequency, bloom_level = EXCLUDED.bloom_level, difficulty = EXCLUDED.difficulty, typical_question_formats = EXCLUDED.typical_question_formats, wiki_items = EXCLUDED.wiki_items, is_computation_heavy = EXCLUDED.is_computation_heavy, three_d_lab_linked = EXCLUDED.three_d_lab_linked, updated_at = now();

-- ── Step 3: Update wiki_items on existing nodes ─────────────────────
UPDATE public.taxonomy_tree SET wiki_items = '[{"text": "Architecture as art and science — the synthesis of aesthetics, structure, and function", "type": "concept"}, {"text": "Vitruvian Triad — Firmitas (strength/structure), Utilitas (function/commodity), Venustas (beauty/delight)", "type": "definition"}, {"text": "Vitruvius — ''De Architectura'' (Ten Books on Architecture, c. 25 BCE), foundational Western architectural treatise", "type": "fact"}, {"text": "Architecture vs. Building — architecture implies intentional design beyond mere shelter", "type": "concept"}, {"text": "The Value of an Architect — professional responsibility, public safety, cultural stewardship, design leadership", "type": "concept"}, {"text": "Architecture as social art — buildings shape human behavior, culture, and community", "type": "concept"}, {"text": "Influences in architectural design: functional, environmental, historical, socio-cultural, technological, economic", "type": "concept"}]'::jsonb, updated_at = now() WHERE ale_id = 'ALE-THEO-001-01';
UPDATE public.taxonomy_tree SET wiki_items = '[{"text": "Phase 1: Pre-Design / Programming — data gathering, client needs, site analysis, program of requirements", "type": "fact"}, {"text": "Phase 2: Schematic Design (SD) — conceptual layouts, bubble diagrams, initial spatial relationships", "type": "fact"}, {"text": "Phase 3: Design Development (DD) — refined plans, sections, elevations, material selection, structural concept", "type": "fact"}, {"text": "Phase 4: Construction Documents (CD) — detailed working drawings, specifications, bidding documents", "type": "fact"}, {"text": "Phase 5: Construction Administration (CA) — site inspection, shop drawing review, change orders, project closeout", "type": "fact"}, {"text": "Design thinking: problem definition → research → ideation → prototyping → testing → iteration", "type": "concept"}, {"text": "Parti — the fundamental idea or concept diagram that organizes a design; the ''big idea''", "type": "definition"}, {"text": "Program vs. Design — programming defines the problem, design proposes the solution", "type": "concept"}]'::jsonb, updated_at = now() WHERE ale_id = 'ALE-THEO-001-02';
UPDATE public.taxonomy_tree SET wiki_items = '[{"text": "Physical Approach — design driven by site conditions, climate, materials, and structural possibilities (Salvan)", "type": "definition"}, {"text": "Intellectual Approach — design as rational problem-solving, analysis of function and efficiency (Salvan)", "type": "definition"}, {"text": "Religious Approach — design shaped by spiritual beliefs, ritual requirements, sacred geometry (Salvan)", "type": "definition"}, {"text": "Symbolic Approach — architecture as carrier of meaning, metaphor, and cultural symbolism (Salvan)", "type": "definition"}, {"text": "Historical Approach — design informed by precedent, typology, and stylistic tradition (Salvan)", "type": "definition"}, {"text": "Behavioral Approach — design based on how people actually use and experience spaces (Salvan)", "type": "definition"}, {"text": "Ecological Approach — design responding to interactions between building and natural environment (Salvan)", "type": "definition"}, {"text": "George Salvan — ''Architectural Theories of Design'' (JMC Press, 1999), primary Filipino reference for design theory", "type": "fact"}]'::jsonb, updated_at = now() WHERE ale_id = 'ALE-THEO-001-03';
UPDATE public.taxonomy_tree SET wiki_items = '[{"text": "Point — marks a position in space; has no dimension; conceptual origin of all form", "type": "definition"}, {"text": "Point as center: two points define a line; the center organizes elements around it", "type": "concept"}, {"text": "Line — extends through space; has length but no width; defines edges, boundaries, contours", "type": "definition"}, {"text": "Line types: vertical (stability, aspiration), horizontal (repose, ground), diagonal (dynamism, movement), curved (organic, flowing)", "type": "fact"}, {"text": "Plane — two-dimensional surface defined by length and width; walls, floors, ceilings as architectural planes", "type": "definition"}, {"text": "Overhead plane (ceiling/roof), wall plane (enclosure/separation), base plane (floor/ground) — three primary architectural planes", "type": "fact"}, {"text": "Volume — three-dimensional form defined by planes; the mass or void of architectural space", "type": "definition"}, {"text": "Francis D.K. Ching — ''Architecture: Form, Space, and Order'' (1979), primary international reference for elements and principles", "type": "fact"}]'::jsonb, updated_at = now() WHERE ale_id = 'ALE-THEO-002-01';
UPDATE public.taxonomy_tree SET wiki_items = '[{"text": "Golden Ratio / Golden Section (φ = 1:1.618) — found in nature, Greek temples, Renaissance art; Fibonacci sequence approximation", "type": "definition"}, {"text": "Fibonacci Sequence (1, 1, 2, 3, 5, 8, 13, 21...) — each number is sum of two preceding; ratio approaches φ", "type": "definition"}, {"text": "Classical Orders as proportional system — column diameter as module; intercolumniation ratios (Vitruvius)", "type": "fact"}, {"text": "Palladian Proportions — room dimensions based on musical harmonic ratios (1:1, 1:2, 2:3, 3:4); ''The Four Books of Architecture'' (1570)", "type": "fact"}, {"text": "Le Corbusier''s Modulor (1948) — proportional system based on human body (1.83m) and Fibonacci/golden ratio; two series (red and blue)", "type": "fact"}, {"text": "Japanese Ken module — tatami mat (approx. 910mm × 1820mm) as basic unit of spatial measurement; room sizes in mat counts", "type": "fact"}, {"text": "Root Rectangles — √2 (ISO paper/A-series), √3, √5 rectangles; dynamic symmetry (Jay Hambidge)", "type": "fact"}, {"text": "Anthropometric Proportion — human body as measure (Vitruvian Man, Leonardo da Vinci; Neufert standards)", "type": "fact"}, {"text": "Relative Proportion — relationship of individual parts to each other and to the whole composition", "type": "definition"}]'::jsonb, updated_at = now() WHERE ale_id = 'ALE-THEO-003-01';
UPDATE public.taxonomy_tree SET wiki_items = '[{"text": "Human Scale — element size relative to human body dimensions; doors, stairs, railings as scale indicators", "type": "definition"}, {"text": "Intimate Scale — spaces proportioned to feel close, warm, and personal (small rooms, low ceilings)", "type": "definition"}, {"text": "Monumental Scale — deliberately oversized to convey grandeur, power, or importance (cathedrals, government buildings)", "type": "definition"}, {"text": "Mechanical Scale — true actual size; 1:1 representation, as in full-scale mockups", "type": "definition"}, {"text": "Visual Scale — perceived or apparent size relative to other elements in the composition; may differ from actual size", "type": "definition"}, {"text": "Generic Scale — the overall scale quality of a work; the dominant impression of size and proportion", "type": "definition"}, {"text": "Shock Scale — dramatic contrast in scale to create surprise or disorientation (Claes Oldenburg sculptures, oversized furniture)", "type": "definition"}, {"text": "Scale-giving elements: human figures, furniture, doors, windows, stairs — familiar objects that establish size reference", "type": "concept"}]'::jsonb, updated_at = now() WHERE ale_id = 'ALE-THEO-003-02';
UPDATE public.taxonomy_tree SET wiki_items = '[{"text": "Anthropometrics — the science of measuring human body dimensions; basis for spatial design standards", "type": "definition"}, {"text": "Static (structural) anthropometry — body dimensions at rest (standing height, sitting height, reach, eye height)", "type": "definition"}, {"text": "Dynamic (functional) anthropometry — body dimensions during movement (reach zones, clearances, operating ranges)", "type": "definition"}, {"text": "Ernst Neufert — ''Architects'' Data'' (Bauentwurfslehre, 1936); standard reference for human dimensions and space requirements", "type": "fact"}, {"text": "Architectural Graphic Standards (Ramsey/Sleeper) — American reference equivalent to Neufert", "type": "fact"}, {"text": "Ergonomics — design of environments, products, and systems for human comfort, safety, and efficiency", "type": "definition"}, {"text": "Percentile design: 5th percentile (small female), 50th percentile (average), 95th percentile (large male) — designing for range", "type": "concept"}, {"text": "Key dimensions: eye height (standing ~1525mm, seated ~1180mm), shoulder breadth (~450mm), door clear width (≥810mm)", "type": "fact"}, {"text": "Filipino anthropometric considerations — generally smaller stature than Western standards; local data important for PH practice", "type": "concept"}]'::jsonb, updated_at = now() WHERE ale_id = 'ALE-THEO-004-01';
UPDATE public.taxonomy_tree SET wiki_items = '[{"text": "Proxemics — the study of human use of space and the effects of spatial distance on behavior (Edward T. Hall, ''The Hidden Dimension,'' 1966)", "type": "definition"}, {"text": "Intimate Distance (0-45cm / 0-18in) — close contact, whisper, physical; reserved for close relationships", "type": "fact"}, {"text": "Personal Distance (45cm-1.2m / 18in-4ft) — arm''s length, personal conversation, friends and family", "type": "fact"}, {"text": "Social Distance (1.2m-3.7m / 4-12ft) — business interactions, formal conversation, acquaintances", "type": "fact"}, {"text": "Public Distance (3.7m+ / 12ft+) — public speaking, lectures, no personal connection expected", "type": "fact"}, {"text": "Cultural variation — proxemic distances vary significantly across cultures; Filipino culture tends toward closer personal distances", "type": "concept"}, {"text": "Kinesics — body movement and gestures as communication; circulation patterns shaped by kinesthetic behavior", "type": "definition"}, {"text": "Edward T. Hall — anthropologist; coined ''proxemics''; wrote ''The Silent Language'' (1959) and ''The Hidden Dimension'' (1966)", "type": "fact"}]'::jsonb, updated_at = now() WHERE ale_id = 'ALE-THEO-004-02';
UPDATE public.taxonomy_tree SET wiki_items = '[{"text": "Territoriality — behavioral pattern of claiming, marking, and defending a particular area as one''s own", "type": "definition"}, {"text": "Primary territory — owned and controlled by individual/group; home, bedroom, personal office; strongest claim", "type": "definition"}, {"text": "Secondary territory — shared, semi-public; neighborhood bar, classroom, club; moderate control", "type": "definition"}, {"text": "Public territory — open to all; parks, streets, plazas; weakest personal claim", "type": "definition"}, {"text": "Defensible Space Theory — Oscar Newman (''Defensible Space,'' 1972); design of housing to reduce crime through natural surveillance, territorial reinforcement", "type": "fact"}, {"text": "CPTED (Crime Prevention Through Environmental Design) — extension of Newman; natural access control, surveillance, maintenance", "type": "definition"}, {"text": "Privacy regulation — Irwin Altman''s theory; privacy as dialectic process of opening and closing to social interaction", "type": "fact"}, {"text": "Crowding — psychological response to perceived density; influenced by control, expectation, and cultural norms", "type": "concept"}]'::jsonb, updated_at = now() WHERE ale_id = 'ALE-THEO-004-03';
UPDATE public.taxonomy_tree SET wiki_items = '[{"text": "Sun Path — east-to-west daily arc; varies seasonally by latitude", "type": "fact"}, {"text": "Solstices — June 21 (summer solstice, sun highest in Northern Hemisphere), December 21 (winter solstice, sun lowest)", "type": "fact"}, {"text": "Equinoxes — March 21 / September 21; sun directly over equator; equal day and night", "type": "fact"}, {"text": "Altitude angle — vertical angle of sun above horizon; determines shadow length and penetration depth", "type": "definition"}, {"text": "Azimuth angle — horizontal angle of sun measured from true north; determines shadow direction", "type": "definition"}, {"text": "Optimal building orientation in tropics: long axis East-West, minimizing east/west wall exposure to low-angle sun", "type": "concept"}, {"text": "Shading Coefficient — ratio of solar heat gain through glazing relative to reference (clear float glass = 1.0)", "type": "definition"}, {"text": "Shadow analysis — plotting shadows at critical times to design overhangs, fins, and shading devices", "type": "concept"}]'::jsonb, updated_at = now() WHERE ale_id = 'ALE-THEO-005-01';
UPDATE public.taxonomy_tree SET wiki_items = '[{"text": "Philippines location: 5°-21°N latitude, tropical maritime climate, within typhoon belt", "type": "fact"}, {"text": "Amihan (NE Monsoon, Nov-Apr) — cooler, drier winds from northeast; dry season for western Philippines", "type": "fact"}, {"text": "Habagat (SW Monsoon, May-Oct) — warm, wet winds from southwest; wet/typhoon season", "type": "fact"}, {"text": "PAGASA Climate Type I — two pronounced seasons: dry (Nov-Apr) and wet (rest of year); Western Philippines", "type": "fact"}, {"text": "PAGASA Climate Type II — no dry season, maximum rainfall Nov-Feb; Eastern Philippines (Surigao, Eastern Samar)", "type": "fact"}, {"text": "PAGASA Climate Type III — short dry season (1-3 months), no pronounced wet/dry; Visayas, parts of Mindanao", "type": "fact"}, {"text": "PAGASA Climate Type IV — evenly distributed rainfall throughout the year; Cotabato, Zamboanga", "type": "fact"}, {"text": "Design implications: high humidity (70-85%), heavy rainfall, strong typhoon winds, earthquake risk; drives elevated structures, steep roofs, natural ventilation", "type": "concept"}]'::jsonb, updated_at = now() WHERE ale_id = 'ALE-THEO-005-02';
UPDATE public.taxonomy_tree SET wiki_items = '[{"text": "Vitruvius (c. 80-15 BCE) — ''De Architectura''; Firmitas, Utilitas, Venustas; first architectural treatise", "type": "fact"}, {"text": "Leon Battista Alberti (1404-1472) — ''De Re Aedificatoria'' (1452); architecture as intellectual discipline; concinnitas (harmony)", "type": "fact"}, {"text": "Andrea Palladio (1508-1580) — ''I Quattro Libri dell''Architettura'' (1570); proportional harmonics; Villa Rotonda; Palladian style", "type": "fact"}, {"text": "Filippo Brunelleschi (1377-1446) — perspective discovery; dome of Florence Cathedral; rational geometry in design", "type": "fact"}, {"text": "Leonardo da Vinci (1452-1519) — Vitruvian Man; Renaissance ideal of architect as universal artist-genius", "type": "fact"}, {"text": "Eugène-Emmanuel Viollet-le-Duc (1814-1879) — structural rationalism; Gothic structure as model; restoration theory", "type": "fact"}, {"text": "John Ruskin (1819-1900) — ''The Seven Lamps of Architecture'' (1849); truth in materials, Gothic as moral architecture", "type": "fact"}, {"text": "Peter Behrens (1868-1940) — ''Master''s Master''; teacher of Gropius, Mies, Le Corbusier; AEG Turbine Factory", "type": "fact"}]'::jsonb, updated_at = now() WHERE ale_id = 'ALE-THEO-006-01';
UPDATE public.taxonomy_tree SET wiki_items = '[{"text": "Frank Lloyd Wright (1867-1959) — Organic Architecture: building as extension of nature; ''form and function are one''", "type": "fact"}, {"text": "Wright — Prairie Houses (Robie House, 1910): horizontal lines, open plan, integration with landscape", "type": "fact"}, {"text": "Wright — Fallingwater (1935): cantilevers over waterfall; Guggenheim Museum NY (1959): spiral ramp gallery", "type": "fact"}, {"text": "Le Corbusier (1887-1965) — ''A house is a machine for living in''; Five Points of Architecture; the Modulor", "type": "fact"}, {"text": "Le Corbusier — Five Points: pilotis, free plan, free façade, ribbon windows, roof garden (Villa Savoye, 1929)", "type": "fact"}, {"text": "Le Corbusier — Unité d''Habitation (1947), Chapel of Ronchamp (1955), Chandigarh master plan (India)", "type": "fact"}, {"text": "Ludwig Mies van der Rohe (1886-1969) — ''Less is more''; ''God is in the details''; universal space, structural clarity", "type": "fact"}, {"text": "Mies — Barcelona Pavilion (1929), Farnsworth House (1951), Seagram Building (1958): glass, steel, open plan", "type": "fact"}, {"text": "Walter Gropius (1883-1969) — ''Architecture begins where engineering ends''; Bauhaus founder (1919); total design", "type": "fact"}, {"text": "Gropius — Bauhaus Building, Dessau (1925): glass curtain wall, interconnected volumes, workshop-meets-academy", "type": "fact"}, {"text": "Adolf Loos (1870-1933) — ''Ornament and Crime'' (1908/1913): ornament is backward; Raumplan (spatial plan); Looshaus, Vienna", "type": "fact"}, {"text": "Louis Sullivan (1856-1924) — ''Form follows function''; father of skyscrapers; ornamental integration; Wainwright Building", "type": "fact"}]'::jsonb, updated_at = now() WHERE ale_id = 'ALE-THEO-006-02';

